for i,(hero,h) in enumerate([('tobin',76),('pip',68)]):
 src=Image.open(R/f'{hero}-contact-source.png').convert('RGBA');bb=src.getchannel('A').point(lambda v:255 if v>=128 else 0).getbbox();im=src.crop(bb);im=im.resize((round(im.width*h/im.height),h),Image.Resampling.NEAREST);alpha=im.getchannel('A').point(lambda v:255 if v>=128 else 0);cols=list(dict.fromkeys(Image.open(f'art/heroes/{hero}/palette.png').convert('RGB').get_flattened_data()));pal=Image.new('P',(1,1));pal.putpalette([v for c in cols+[cols[0]]*(256-len(cols)) for v in c]);im=im.convert('RGB').quantize(palette=pal,dither=Image.Dither.NONE).convert('RGBA');im.putalpha(alpha);feet=[x for y in range(h-6,h) for x in range(round(im.width*.7)) if im.getpixel((x,y))[3]];anchor=round(sum(feet)/len(feet));out=Image.new('RGBA',(224,192));origin=(96-anchor,132-h);out.paste(im,origin);out.save(R/f'{hero}-contact-native.png');report.append({'hero':hero,'status':'pose-review-pending','canvas':[224,192],'groundAnchor':[96,132],'crouchedHeight':h,'footSampleExcludesTool':True,'sourceBBox':bb,'origin':origin,'equipmentBakedIn':True,'contactHeightTarget':[12,20]});large=out.resize((448,384),Image.Resampling.NEAREST);sheet.paste(large,(i*448,0),large);d.text((i*448+8,10),hero+' low lateral sickle contact draft',fill='white')
